import{_ as l,r as t,o as i,c as u,e as p,a as n,s as e,d as a}from"./chunks/framework.CXcwiNg-.js";const b=JSON.parse('{"title":"事件 - October CMS - 2.x","titleTemplate":false,"description":"","frontmatter":{},"headers":[{"level":2,"title":"基本用法","slug":"基本用法","link":"#基本用法","children":[]},{"level":2,"title":"监听事件","slug":"监听事件","link":"#监听事件","children":[{"level":3,"title":"在哪里注册监听器","slug":"在哪里注册监听器","link":"#在哪里注册监听器","children":[]},{"level":3,"title":"使用优先级监听","slug":"使用优先级监听","link":"#使用优先级监听","children":[]},{"level":3,"title":"停止事件","slug":"停止事件","link":"#停止事件","children":[]},{"level":3,"title":"通配符监听器","slug":"通配符监听器","link":"#通配符监听器","children":[]}]},{"level":2,"title":"触发事件","slug":"触发事件","link":"#触发事件","children":[]},{"level":2,"title":"通过引用传递参数","slug":"通过引用传递参数","link":"#通过引用传递参数","children":[{"level":3,"title":"队列事件","slug":"队列事件","link":"#队列事件","children":[]}]},{"level":2,"title":"使用类作为监听器","slug":"使用类作为监听器","link":"#使用类作为监听器","children":[{"level":3,"title":"监听单个方法","slug":"监听单个方法","link":"#监听单个方法","children":[]},{"level":3,"title":"监听整个类","slug":"监听整个类","link":"#监听整个类","children":[]}]},{"level":2,"title":"事件派发器特征","slug":"事件派发器特征","link":"#事件派发器特征","children":[]}],"relativePath":"2.x/zh-cn/services/events.md","filePath":"2.x/zh-cn/services/events.md"}'),r={name:"2.x/zh-cn/services/events.md"};function k(d,s,g,v,h,f){const o=t("pre-heading"),c=t("post-heading");return i(),u("div",null,[p(o),s[0]||(s[0]=n("h1",null,"事件",-1)),p(c),s[1]||(s[1]=e(`<h2 id="基本用法"><a href="#基本用法" class="header-anchor">#</a> 基本用法</h2><p><code>Event</code> 类提供了一个简单的观察者实现，允许您订阅和监听应用程序中的事件。 例如，您可以监听用户何时登录并更新他们的上次登录日期。</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token class-name static-context">Event</span><span class="token operator">::</span><span class="token function">listen</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;auth.login&#39;</span><span class="token punctuation">,</span> <span class="token keyword">function</span><span class="token punctuation">(</span><span class="token variable">$user</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
    <span class="token variable">$user</span><span class="token operator">-&gt;</span><span class="token property">last_login</span> <span class="token operator">=</span> <span class="token keyword">new</span> <span class="token class-name">DateTime</span><span class="token punctuation">;</span>
    <span class="token variable">$user</span><span class="token operator">-&gt;</span><span class="token function">save</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><p>这是通过 <code>Event::fire</code> 方法提供的事件，该方法作为用户登录逻辑的一部分调用，从而使逻辑可扩展。</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token class-name static-context">Event</span><span class="token operator">::</span><span class="token function">fire</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;auth.login&#39;</span><span class="token punctuation">,</span> <span class="token punctuation">[</span><span class="token variable">$user</span><span class="token punctuation">]</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div>`,5)),s[2]||(s[2]=n("blockquote",null,[n("p",null,[n("strong",null,"注意"),a("：有关 October CMS 本身中可用的所有事件的列表，请参阅 "),n("a",{href:"https://octobercms.com/docs/api",target:"_blank",rel:"noopener noreferrer",class:"is-ext"},[a("API 文档"),n("span",null,[n("svg",{xmlns:"http://www.w3.org/2000/svg","aria-hidden":"true",focusable:"false",x:"0px",y:"0px",viewBox:"0 0 100 100",width:"15",height:"15",class:"icon outbound"},[n("path",{fill:"currentColor",d:"M18.8,85.1h56l0,0c2.2,0,4-1.8,4-4v-32h-8v28h-48v-48h28v-8h-32l0,0c-2.2,0-4,1.8-4,4v56C14.8,83.3,16.6,85.1,18.8,85.1z"}),a(),n("polygon",{fill:"currentColor",points:"45.7,48.7 51.3,54.3 77.2,28.5 77.2,37.2 85.2,37.2 85.2,14.9 62.8,14.9 62.8,22.9 71.5,22.9"})]),a(),n("span",{class:"sr-only"},"(opens new window)")])]),a("。")])],-1)),s[3]||(s[3]=e(`<p><a id="oc-subscribing-to-events"></a></p><h2 id="监听事件"><a href="#监听事件" class="header-anchor">#</a> 监听事件</h2><p><code>Event::listen</code> 方法主要用于监听事件，可以在应用程序代码中的任何位置完成。 第一个参数是事件名称。</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token class-name static-context">Event</span><span class="token operator">::</span><span class="token function">listen</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;acme.blog.myevent&#39;</span><span class="token punctuation">,</span> <span class="token operator">...</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><p>第二个参数可以是一个闭包，它指定触发事件时应该发生什么。 闭包可以接受一些可选的参数，由 <a href="#oc-firing-events">触发事件</a> 提供。</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token class-name static-context">Event</span><span class="token operator">::</span><span class="token function">listen</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;acme.blog.myevent&#39;</span><span class="token punctuation">,</span> <span class="token keyword">function</span><span class="token punctuation">(</span><span class="token variable">$arg1</span><span class="token punctuation">,</span> <span class="token variable">$arg2</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
    <span class="token comment">// 做</span>
<span class="token punctuation">}</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><p>您还可以传递对任何可调用对象或 <a href="#oc-using-classes-as-listeners">专用事件类</a> 的引用，并将使用它来代替。</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token class-name static-context">Event</span><span class="token operator">::</span><span class="token function">listen</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;auth.login&#39;</span><span class="token punctuation">,</span> <span class="token punctuation">[</span><span class="token variable">$this</span><span class="token punctuation">,</span> <span class="token string single-quoted-string">&#39;LoginHandler&#39;</span><span class="token punctuation">]</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><blockquote><p><strong>注意</strong>：可调用方法可以选择指定全部、部分或不指定任何参数。 无论哪种方式，事件都不会引发任何错误，除非它指定太多。</p></blockquote><p><a id="oc-where-to-register-listeners"></a></p><h3 id="在哪里注册监听器"><a href="#在哪里注册监听器" class="header-anchor">#</a> 在哪里注册监听器</h3><p>最常见的地方是<a href="./../plugin/registration.html#oc-registration-methods">插件注册文件</a>的<code>boot</code>方法。</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">class</span> <span class="token class-name-definition class-name">Plugin</span> <span class="token keyword">extends</span> <span class="token class-name">PluginBase</span>
<span class="token punctuation">{</span>
    <span class="token comment">// ...</span>

    <span class="token keyword">public</span> <span class="token keyword">function</span> <span class="token function-definition function">boot</span><span class="token punctuation">(</span><span class="token punctuation">)</span>
    <span class="token punctuation">{</span>
        <span class="token class-name static-context">Event</span><span class="token operator">::</span><span class="token function">listen</span><span class="token punctuation">(</span><span class="token operator">...</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
    <span class="token punctuation">}</span>
<span class="token punctuation">}</span>
</code></pre></div><p>或者，插件可以在插件目录中提供一个名为 <strong>init.php</strong> 的文件，您可以使用它来放置事件注册逻辑。 例如：</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token php language-php"><span class="token delimiter important">&lt;?php</span>

<span class="token class-name static-context">Event</span><span class="token operator">::</span><span class="token function">listen</span><span class="token punctuation">(</span><span class="token operator">...</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</span></code></pre></div><p>由于这些方法都不是本质上&quot;正确&quot;的，因此请根据应用程序的大小选择您觉得合适的方法。</p><h3 id="使用优先级监听"><a href="#使用优先级监听" class="header-anchor">#</a> 使用优先级监听</h3><p>您还可以在监听事件时指定优先级作为第三个参数。 优先级较高的监听器将首先运行，而具有相同优先级的监听器将按监听顺序运行。</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token comment">// 第一个运行</span>
<span class="token class-name static-context">Event</span><span class="token operator">::</span><span class="token function">listen</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;auth.login&#39;</span><span class="token punctuation">,</span> <span class="token keyword">function</span><span class="token punctuation">(</span><span class="token punctuation">)</span> <span class="token punctuation">{</span> <span class="token operator">...</span> <span class="token punctuation">}</span><span class="token punctuation">,</span> <span class="token number">10</span><span class="token punctuation">)</span><span class="token punctuation">;</span>

<span class="token comment">// 第二个运行</span>
<span class="token class-name static-context">Event</span><span class="token operator">::</span><span class="token function">listen</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;auth.login&#39;</span><span class="token punctuation">,</span> <span class="token keyword">function</span><span class="token punctuation">(</span><span class="token punctuation">)</span> <span class="token punctuation">{</span> <span class="token operator">...</span> <span class="token punctuation">}</span><span class="token punctuation">,</span> <span class="token number">5</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><p><a id="oc-halting-events"></a></p><h3 id="停止事件"><a href="#停止事件" class="header-anchor">#</a> 停止事件</h3><p>有时您可能希望停止将事件传播给其他监听器。 您可以通过从监听器返回 <code>false</code> 来执行此操作：</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token class-name static-context">Event</span><span class="token operator">::</span><span class="token function">listen</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;auth.login&#39;</span><span class="token punctuation">,</span> <span class="token keyword">function</span><span class="token punctuation">(</span><span class="token variable">$event</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
    <span class="token comment">// 处理事件</span>

    <span class="token keyword">return</span> <span class="token constant boolean">false</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><h3 id="通配符监听器"><a href="#通配符监听器" class="header-anchor">#</a> 通配符监听器</h3><p>注册事件监听器时，您可以使用星号指定通配符监听器。 通配符监听器接收首先触发的事件名称，然后是作为数组传递给事件的参数。</p><p>以下监听器处理所有以 <code>foo.</code> 开头的事件。</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token class-name static-context">Event</span><span class="token operator">::</span><span class="token function">listen</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;foo.*&#39;</span><span class="token punctuation">,</span> <span class="token keyword">function</span><span class="token punctuation">(</span><span class="token variable">$event</span><span class="token punctuation">,</span> <span class="token variable">$params</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
    <span class="token comment">// 处理事件...</span>
<span class="token punctuation">}</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><p>您可以使用 <code>Event::firing</code> 方法来准确确定触发了哪个事件。</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token class-name static-context">Event</span><span class="token operator">::</span><span class="token function">listen</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;foo.*&#39;</span><span class="token punctuation">,</span> <span class="token keyword">function</span><span class="token punctuation">(</span><span class="token variable">$event</span><span class="token punctuation">,</span> <span class="token variable">$params</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
    <span class="token keyword">if</span> <span class="token punctuation">(</span><span class="token class-name static-context">Event</span><span class="token operator">::</span><span class="token function">firing</span><span class="token punctuation">(</span><span class="token punctuation">)</span> <span class="token operator">===</span> <span class="token string single-quoted-string">&#39;foo.bar&#39;</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
        <span class="token comment">// ...</span>
    <span class="token punctuation">}</span>
<span class="token punctuation">}</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><p><a id="oc-firing-events"></a></p><h2 id="触发事件"><a href="#触发事件" class="header-anchor">#</a> 触发事件</h2><p>您可以在代码中的任何位置使用 <code>Event::fire</code> 方法来使逻辑可扩展。 这意味着其他开发人员，甚至您自己的内部代码，都可以&quot;挂钩&quot;到这一个代码并注入特定的逻辑。 第一个参数应该是事件名称。</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token class-name static-context">Event</span><span class="token operator">::</span><span class="token function">fire</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;myevent&#39;</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><p>使用插件命名空间代码为事件名称添加前缀总是一个好主意，这将防止与其他插件发生冲突。</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token class-name static-context">Event</span><span class="token operator">::</span><span class="token function">fire</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;acme.blog.myevent&#39;</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><p>第二个参数是一个值数组，将作为参数传递给监听它的 <a href="#oc-subscribing-to-events">事件监听器</a>。</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token class-name static-context">Event</span><span class="token operator">::</span><span class="token function">fire</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;acme.blog.myevent&#39;</span><span class="token punctuation">,</span> <span class="token punctuation">[</span><span class="token variable">$arg1</span><span class="token punctuation">,</span> <span class="token variable">$arg2</span><span class="token punctuation">]</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><p>第三个参数指定事件是否应该是 <a href="#oc-halting-events">停止事件</a>，这意味着如果返回&quot;非 null&quot;值，它应该停止。此参数默认设置为 false。</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token class-name static-context">Event</span><span class="token operator">::</span><span class="token function">fire</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;acme.blog.myevent&#39;</span><span class="token punctuation">,</span> <span class="token punctuation">[</span><span class="token operator">...</span><span class="token punctuation">]</span><span class="token punctuation">,</span> <span class="token constant boolean">true</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><p>如果事件正在停止，则返回的第一个值被捕获。</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token comment">// 单一结果，事件停止</span>
<span class="token variable">$result</span> <span class="token operator">=</span> <span class="token class-name static-context">Event</span><span class="token operator">::</span><span class="token function">fire</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;acme.blog.myevent&#39;</span><span class="token punctuation">,</span> <span class="token punctuation">[</span><span class="token operator">...</span><span class="token punctuation">]</span><span class="token punctuation">,</span> <span class="token constant boolean">true</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><p>否则，它将以数组的形式返回来自所有事件的所有响应的集合。</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token comment">// 多个结果，所有事件都被触发</span>
<span class="token variable">$results</span> <span class="token operator">=</span> <span class="token class-name static-context">Event</span><span class="token operator">::</span><span class="token function">fire</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;acme.blog.myevent&#39;</span><span class="token punctuation">,</span> <span class="token punctuation">[</span><span class="token operator">...</span><span class="token punctuation">]</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><h2 id="通过引用传递参数"><a href="#通过引用传递参数" class="header-anchor">#</a> 通过引用传递参数</h2><p>在处理或过滤传递给事件的值时，您可以在变量前面加上 <code>&amp;</code> 以通过引用传递它。这允许多个监听器操纵结果并将其传递给下一个监听器。</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token class-name static-context">Event</span><span class="token operator">::</span><span class="token function">fire</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;cms.processContent&#39;</span><span class="token punctuation">,</span> <span class="token punctuation">[</span><span class="token operator">&amp;</span><span class="token variable">$content</span><span class="token punctuation">]</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><p>监听事件时，参数也需要在闭包定义中用 <code>&amp;</code> 符号声明。在下面的示例中，<code>$content</code> 变量将在结果中附加&quot;AB&quot;。</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token class-name static-context">Event</span><span class="token operator">::</span><span class="token function">listen</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;cms.processContent&#39;</span><span class="token punctuation">,</span> <span class="token keyword">function</span> <span class="token punctuation">(</span><span class="token operator">&amp;</span><span class="token variable">$content</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
    <span class="token variable">$content</span> <span class="token operator">=</span> <span class="token variable">$content</span> <span class="token operator">.</span> <span class="token string single-quoted-string">&#39;A&#39;</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span><span class="token punctuation">)</span><span class="token punctuation">;</span>

<span class="token class-name static-context">Event</span><span class="token operator">::</span><span class="token function">listen</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;cms.processContent&#39;</span><span class="token punctuation">,</span> <span class="token keyword">function</span> <span class="token punctuation">(</span><span class="token operator">&amp;</span><span class="token variable">$content</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
    <span class="token variable">$content</span> <span class="token operator">=</span> <span class="token variable">$content</span> <span class="token operator">.</span> <span class="token string single-quoted-string">&#39;B&#39;</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><h3 id="队列事件"><a href="#队列事件" class="header-anchor">#</a> 队列事件</h3><p>触发事件可以在 <a href="./../services/queues.html">与队列结合使用</a> 中延迟。使用 <code>Event::queue</code> 方法将事件&quot;排队&quot;触发，但不立即触发。</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token class-name static-context">Event</span><span class="token operator">::</span><span class="token function">queue</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;foo&#39;</span><span class="token punctuation">,</span> <span class="token punctuation">[</span><span class="token variable">$user</span><span class="token punctuation">]</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><p>您可以使用 <code>Event::flush</code> 方法刷新所有排队的事件。</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token class-name static-context">Event</span><span class="token operator">::</span><span class="token function">flush</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;foo&#39;</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><p><a id="oc-using-classes-as-listeners"></a></p><h2 id="使用类作为监听器"><a href="#使用类作为监听器" class="header-anchor">#</a> 使用类作为监听器</h2><p>在某些情况下，您可能希望使用类而不是闭包来处理事件。类事件监听器将从 <a href="./application.html">Application IoC 容器</a> 中解析出来，为您提供监听器依赖注入的全部功能。</p><h3 id="监听单个方法"><a href="#监听单个方法" class="header-anchor">#</a> 监听单个方法</h3><p>事件类可以像任何其他方法一样使用 <code>Event::listen</code> 方法注册，将类名作为字符串传递。</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token class-name static-context">Event</span><span class="token operator">::</span><span class="token function">listen</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;auth.login&#39;</span><span class="token punctuation">,</span> <span class="token string single-quoted-string">&#39;LoginHandler&#39;</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><p>默认情况下，会调用 <code>LoginHandler</code> 类的 <code>handle</code> 方法：</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">class</span> <span class="token class-name-definition class-name">LoginHandler</span>
<span class="token punctuation">{</span>
    <span class="token keyword">public</span> <span class="token keyword">function</span> <span class="token function-definition function">handle</span><span class="token punctuation">(</span><span class="token variable">$data</span><span class="token punctuation">)</span>
    <span class="token punctuation">{</span>
        <span class="token comment">// ...</span>
    <span class="token punctuation">}</span>
<span class="token punctuation">}</span>
</code></pre></div><p>如果你不想使用默认的 <code>handle</code> 方法，你可以指定应该监听的方法名。</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token class-name static-context">Event</span><span class="token operator">::</span><span class="token function">listen</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;auth.login&#39;</span><span class="token punctuation">,</span> <span class="token string single-quoted-string">&#39;LoginHandler@onLogin&#39;</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><h3 id="监听整个类"><a href="#监听整个类" class="header-anchor">#</a> 监听整个类</h3><p>事件订阅者是可以从类本身监听多个事件的类。订阅者应该定义一个 <code>subscribe</code> 方法，该方法将被传递一个事件调度程序实例。</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">class</span> <span class="token class-name-definition class-name">UserEventHandler</span>
<span class="token punctuation">{</span>
    <span class="token comment">/**
     * 处理用户登录事件。
     */</span>
    <span class="token keyword">public</span> <span class="token keyword">function</span> <span class="token function-definition function">userLogin</span><span class="token punctuation">(</span><span class="token variable">$event</span><span class="token punctuation">)</span>
    <span class="token punctuation">{</span>
        <span class="token comment">// ...</span>
    <span class="token punctuation">}</span>

    <span class="token comment">/**
     * 处理用户注销事件。
     */</span>
    <span class="token keyword">public</span> <span class="token keyword">function</span> <span class="token function-definition function">userLogout</span><span class="token punctuation">(</span><span class="token variable">$event</span><span class="token punctuation">)</span>
    <span class="token punctuation">{</span>
        <span class="token comment">// ...</span>
    <span class="token punctuation">}</span>

    <span class="token comment">/**
     * 为订阅者注册监听器。
     *
     * @param  Illuminate\\Events\\Dispatcher  $events
     * @return array
     */</span>
    <span class="token keyword">public</span> <span class="token keyword">function</span> <span class="token function-definition function">subscribe</span><span class="token punctuation">(</span><span class="token variable">$events</span><span class="token punctuation">)</span>
    <span class="token punctuation">{</span>
        <span class="token variable">$events</span><span class="token operator">-&gt;</span><span class="token function">listen</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;auth.login&#39;</span><span class="token punctuation">,</span> <span class="token string single-quoted-string">&#39;UserEventHandler@userLogin&#39;</span><span class="token punctuation">)</span><span class="token punctuation">;</span>

        <span class="token variable">$events</span><span class="token operator">-&gt;</span><span class="token function">listen</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;auth.logout&#39;</span><span class="token punctuation">,</span> <span class="token string single-quoted-string">&#39;UserEventHandler@userLogout&#39;</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
    <span class="token punctuation">}</span>
<span class="token punctuation">}</span>
</code></pre></div><p>一旦定义了订阅者，就可以使用 <code>Event::subscribe</code> 方法注册它。</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token class-name static-context">Event</span><span class="token operator">::</span><span class="token function">subscribe</span><span class="token punctuation">(</span><span class="token keyword">new</span> <span class="token class-name">UserEventHandler</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><p>您也可以使用 <a href="./application.html">Application IoC 容器</a> 来解析您的订阅者。为此，只需将订阅者的名称传递给 <code>subscribe</code> 方法。</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token class-name static-context">Event</span><span class="token operator">::</span><span class="token function">subscribe</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;UserEventHandler&#39;</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><h2 id="事件派发器特征"><a href="#事件派发器特征" class="header-anchor">#</a> 事件派发器特征</h2><p>有时您希望将事件绑定到对象的单个实例。您可以通过在类中实现 <code>October\\Rain\\Support\\Traits\\Emitter</code> 特征来使用替代事件系统。</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">class</span> <span class="token class-name-definition class-name">UserManager</span>
<span class="token punctuation">{</span>
    <span class="token keyword">use</span> <span class="token package"><span class="token punctuation">\\</span>October<span class="token punctuation">\\</span>Rain<span class="token punctuation">\\</span>Support<span class="token punctuation">\\</span>Traits<span class="token punctuation">\\</span>Emitter</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span>
</code></pre></div><p>此特征提供了一种使用 <code>bindEvent</code> 监听事件的方法。</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token variable">$manager</span> <span class="token operator">=</span> <span class="token keyword">new</span> <span class="token class-name">UserManager</span><span class="token punctuation">;</span>
<span class="token variable">$manager</span><span class="token operator">-&gt;</span><span class="token function">bindEvent</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;user.beforeRegister&#39;</span><span class="token punctuation">,</span> <span class="token keyword">function</span><span class="token punctuation">(</span><span class="token variable">$user</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
    <span class="token comment">// 检查 $user 是否是垃圾邮件发送者</span>
<span class="token punctuation">}</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><p><code>fireEvent</code> 方法用于触发事件。</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token variable">$manager</span> <span class="token operator">=</span> <span class="token keyword">new</span> <span class="token class-name">UserManager</span><span class="token punctuation">;</span>
<span class="token variable">$manager</span><span class="token operator">-&gt;</span><span class="token function">fireEvent</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;user.beforeRegister&#39;</span><span class="token punctuation">,</span> <span class="token punctuation">[</span><span class="token variable">$user</span><span class="token punctuation">]</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><p>这些事件只会发生在本地对象上，而不是全局发生。</p>`,78))])}const x=l(r,[["render",k]]);export{b as __pageData,x as default};
